// Aircraft type tiers (docs/DESIGN-LOOP.md §1, approved by Sevaan 2026-11-17). A card has one tier everywhere.
// Generated by scripts/research/build-tiers.py from the 24-hour sample study (17,720 aircraft at 27 places): the 15
// most-seen types are Common (55.6% of sightings), ranks 16-60 Uncommon (26.3%), every other type Rare.
// Common light, business and regional types the sample under-counts are lifted to Uncommon by hand (LIFT_UNCOMMON in the
// script, 2026-11-19); E75S joins E75L in Common; military types Epic again (Sevaan 2026-11-19: caught by type, never by callsign or unit); no retired types. Epic and Legendary are hand lists (the ones people point at; edit them in the script): 3.6% and 0.0%.
export const COMMON_TYPES = new Set(["B738", "B38M", "A320", "A21N", "A20N", "A321", "B789", "B77W", "A359", "C172", "E75L", "E75S", "A333", "P28A", "B77L", "B788"]);
export const UNCOMMON_TYPES = new Set(["A319", "BCS3", "B763", "B737", "B739", "B39M", "B772", "CRJ9", "DH8D", "E190", "E295", "A332", "B78X", "E55P", "A35K", "GLEX", "PC12", "CL35", "CL60", "A339", "C56X", "CRJ7", "C68A", "BE20", "C208", "C152", "B752", "GLF4", "GLF5", "SR22", "F2TH", "GLF6", "E170", "AT76", "GL7T", "C25B", "H25B", "CL30", "C25A", "E545", "R44", "E145", "B350", "B190", "C750", "C182", "C206", "C210", "BE36", "BE35", "BE58", "DA40", "DA42", "DA62", "SR20", "P28R", "PA32", "PA34", "PA46", "M20P", "C150", "CRJ2", "AT72", "AT75", "AT45", "B736", "B712", "B753", "B762", "B764", "A318", "E135", "DH8C", "DH8B", "BE9L"]);
export const EPIC_TYPES = new Set(["B741", "B742", "B743", "B744", "B748", "B74S", "B74R", "B74D", "BLCF", "A388", "A342", "A343", "A345", "A346", "MD11", "DC10", "C17", "C130", "C30J", "C5M", "A400", "K35R", "K35E", "KC10", "E3TF", "E3CF", "E6", "B52", "B1", "B2", "P8", "C2", "AN12", "IL76", "IL96", "C295", "V22", "U2", "F16", "F18", "F35", "F15", "EUFI", "A10", "H47", "H53"]);
export const LEGENDARY_TYPES = new Set(["A124", "A3ST", "A337", "SHIP", "BALL", "DC3", "B17", "B29", "LANC", "SPIT", "JU52", "P51"]);
// heli: helicopters are Rare whatever the type (0-11% of traffic by place).
export function typeTier(type, heli = false) {
  const t = String(type || '').toUpperCase();
  if (LEGENDARY_TYPES.has(t)) return 'legendary';
  if (EPIC_TYPES.has(t)) return 'epic';
  if (heli) return 'rare';
  if (COMMON_TYPES.has(t)) return 'common';
  if (UNCOMMON_TYPES.has(t)) return 'uncommon';
  return t ? 'rare' : 'common'; // no type code at all: an unknown aircraft is nothing special
}
